// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Ended drafts in history"
// Changes: MCP-level tests for ended drafts: an adopted draft is listed with its state, it and its snapshots stay
//          readable, and every write to it is refused. A deleted ended draft is gone for agents too.

import { describe, expect, it } from 'vitest'
import { defaultProjectData } from '#/lib/project'
import { agentHarness } from './agentTestHarness'

const h = agentHarness()

async function adoptedDraft() {
  const project = h.store.createProject('Výrazy', { ...defaultProjectData(), ll: { grammar: 'E -> id', input: '' } })
  const { draft } = await h.call('create_draft', { project: project.id, label: 'Návrh' })
  const target = { kind: 'draft', id: draft.id }
  await h.call('set_grammar_rules', { target, text: 'E -> ( E )\nE -> id' })
  h.advance(60_000)
  h.store.adoptDraft(draft.id, ['grammarRules'], project.revision)
  return { project, target }
}

describe('ended drafts over the agent interface', () => {
  it('an adopted draft is listed with its state and end time', async () => {
    const { project, target } = await adoptedDraft()
    const { drafts } = await h.call('list_drafts', { project: project.id })
    expect(drafts).toEqual([expect.objectContaining({ id: target.id, state: 'adopted', endedAt: '2026-01-01T10:01:00.000Z' })])
  })

  it('an adopted draft and its final snapshot stay readable', async () => {
    const { target } = await adoptedDraft()
    const part = await h.call('get_part', { target, part: 'grammarRules' })
    expect(part.value).toBe('E -> ( E )\nE -> id')
    expect(part.target).toMatchObject({ kind: 'draft', state: 'adopted' })

    const { snapshots } = await h.call('list_snapshots', { target })
    expect(snapshots[0]).toMatchObject({ kind: 'final', label: 'Prevzatý návrh „Návrh“' })
    const fromSnapshot = await h.call('get_part', { target: { kind: 'snapshot', id: snapshots[0].id }, part: 'grammarRules' })
    expect(fromSnapshot.value).toBe('E -> ( E )\nE -> id')
  })

  it('writes to an adopted draft are refused', async () => {
    const { target } = await adoptedDraft()
    for (const [tool, args] of [
      ['set_grammar_rules', { text: 'E -> x' }],
      ['set_relation', { stack: '+', input: 'id', relation: '<' }],
      ['relabel_draft', { label: 'x' }],
      ['discard_draft', {}],
    ] as const) {
      expect((await h.call(tool, { target, ...args })).error).toMatch(/adopted.*read-only/i)
    }
  })

  it('a deleted ended draft is no longer listed or readable', async () => {
    const { project, target } = await adoptedDraft()
    h.store.deleteEndedDraft(target.id)
    expect((await h.call('list_drafts', { project: project.id })).drafts).toEqual([])
    expect((await h.call('get_part', { target, part: 'grammarRules' })).error).toMatch(/no draft/i)
  })
})
